Fixed-size buffer of 8192 bytes may be insufficient for large environment blocks. Consider using dynamic allocation or handling partial reads to prevent truncation of environment data.
```suggestion
    size_t buffer_size = 8192;
    size_t total_read = 0;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        close(fd);
        return NULL;
    }
    ssize_t bytes_read;
    while ((bytes_read = read(fd, buffer + total_read, buffer_size - total_read)) > 0) {
        total_read += bytes_read;
        // If buffer is full, grow it
        if (total_read == buffer_size) {
            size_t new_size = buffer_size * 2;
            char *new_buffer = realloc(buffer, new_size);
            if (!new_buffer) {
                free(buffer);
                close(fd);
                return NULL;
            }
            buffer = new_buffer;
            buffer_size = new_size;
        }
    }
    close(fd);
    if (total_read == 0) {
        free(buffer);
        return NULL;
    }
    // Ensure buffer is null-terminated for searching
    if (total_read == buffer_size) {
        // Grow buffer for null terminator
        char *new_buffer = realloc(buffer, buffer_size + 1);
        if (!new_buffer) {
            free(buffer);
            return NULL;
        }
        buffer = new_buffer;
        buffer_size++;
    }
    buffer[total_read] = '\0';

    size_t var_len = strlen(var_name);
    char *pos = buffer;
    char *end = buffer + total_read;
