And it is more precise to test `3.8`+ kernel version.

```sh
    _kernel_ver=$(uname -r)
    _kernel_major_ver=${_kernel_ver%%.*}
    _kernel_remaining_ver=${_kernel_ver#*.}
    _kernel_minor_ver=${_kernel_remaining_ver%%.*}
    [ ${_kernel_major_ver} -gt 3 ] && return 0
